//! Active DNS discovery.
//!
//! Every passive corpus has the same blind spot: it can only report a name that
//! *something already recorded*. A host that never got a certificate, was never
//! crawled and was never resolved from a monitored resolver is invisible to all
//! of them at once — and those are disproportionately the interesting ones:
//! staging copies, admin panels, forgotten migrations.
//!
//! Reaching them means asking DNS directly. Four techniques, in ascending order
//! of how much they cost:
//!
//! 1. **NSEC zone walking** — free and *complete*. A DNSSEC zone signed with
//!    NSEC hands over its own contents: each denial-of-existence answer names
//!    the next owner in canonical order, so following the chain enumerates the
//!    entire zone with no guessing (RFC 4034 §4). Zones using NSEC3 hash the
//!    names and are not walkable here.
//! 2. **SRV probing** — a fixed, small set of service labels (`_sip._tcp`,
//!    `_autodiscover._tcp`, `_ldap._tcp`, …) whose targets routinely name
//!    internal-facing hosts nothing else advertises.
//! 3. **Brute force** — a curated label list resolved against the zone.
//! 4. **Permutation** — mutate the names already known to exist (`api` →
//!    `api-dev`, `api2`, `dev.api`). This is what turns a 30-name passive
//!    result into a 200-name inventory, and it only works *after* the passive
//!    pass, because it needs known-good names to mutate.
//!
//! ## Wildcards come first
//!
//! None of 2–4 mean anything until wildcards are handled. A zone with
//! `*.example.com A 1.2.3.4` answers *every* query, so a naive brute force
//! "finds" the whole wordlist. [`WildcardProfile`] establishes a per-zone
//! baseline from random labels that cannot plausibly exist, and every candidate
//! is checked against it before being accepted. This is the same discipline
//! `puredns` and `shuffledns` apply, and skipping it is the single most common
//! way an enumeration pipeline produces garbage.

use crate::error::ApiError;
use crate::services::external::DnsResolver;
use crate::services::scanners::dns_wire;
use futures::stream::{self, StreamExt};
use rand::Rng;
use std::collections::{BTreeSet, HashMap, HashSet};
use std::net::IpAddr;
use std::sync::Arc;
use std::time::Duration;
use trust_dns_resolver::proto::rr::{RData, RecordType};

/// Curated default label list, ordered by real-world hit rate.
const DEFAULT_SUBDOMAIN_WORDLIST: &str = include_str!("wordlists/subdomains.txt");
/// Vocabulary glued onto known-good names to form permutations.
const DEFAULT_PERMUTATION_WORDS: &str = include_str!("wordlists/permutations.txt");
/// `_service._proto` labels worth a direct SRV query.
const DEFAULT_SRV_SERVICES: &str = include_str!("wordlists/srv_services.txt");

/// How many random labels are probed to characterise a zone's wildcard.
///
/// One probe cannot tell a wildcard with a stable answer from a wildcard that
/// rotates addresses. Three can, and three queries per zone is cheap.
const WILDCARD_PROBE_COUNT: usize = 3;

/// Upper bound on names generated by permutation, before resolution.
///
/// Permutation output grows as `known × words × patterns`; on a large passive
/// result that is millions of names. The cap keeps a discovery run bounded.
const PERMUTATION_HARD_CAP: usize = 25_000;

/// Maximum NSEC hops before the walk is abandoned.
///
/// A correct walk terminates when the chain returns to the apex. The cap exists
/// for zones that are broken, deliberately looping, or simply enormous.
const NSEC_MAX_STEPS: usize = 5_000;

/// Configuration for the active DNS stage.
#[derive(Debug, Clone)]
pub struct ActiveDnsConfig {
    pub bruteforce_enabled: bool,
    pub permutations_enabled: bool,
    pub nsec_walk_enabled: bool,
    pub srv_probe_enabled: bool,
    /// Concurrent in-flight resolutions. The resolver applies its own rate
    /// limit underneath; this bounds memory and socket use.
    pub concurrency: usize,
    /// Labels taken from the wordlist. Truncating a hit-rate-ordered list keeps
    /// the highest-yield names.
    pub max_bruteforce_words: usize,
    /// Ceiling on generated permutations after the hard cap.
    pub max_permutations: usize,
    /// Known-good names used as permutation seeds, highest confidence first.
    pub max_permutation_seeds: usize,
    /// Optional operator-supplied wordlist, replacing the built-in list.
    pub wordlist_path: Option<String>,
    pub query_timeout: Duration,
}

impl Default for ActiveDnsConfig {
    fn default() -> Self {
        Self {
            bruteforce_enabled: true,
            permutations_enabled: true,
            nsec_walk_enabled: true,
            srv_probe_enabled: true,
            concurrency: 50,
            max_bruteforce_words: 2_000,
            max_permutations: 5_000,
            max_permutation_seeds: 50,
            wordlist_path: None,
            query_timeout: Duration::from_secs(5),
        }
    }
}

/// What a zone does with names that do not exist.
#[derive(Debug, Clone, Default)]
pub struct WildcardProfile {
    /// Zone suffix -> the addresses its wildcard answers with.
    wildcard_ips: HashMap<String, HashSet<IpAddr>>,
    /// Zones whose wildcard returns a different answer every time. Nothing
    /// resolved under these can be trusted on resolution alone.
    rotating: HashSet<String>,
}

impl WildcardProfile {
    pub fn is_wildcarded(&self, zone: &str) -> bool {
        self.wildcard_ips.contains_key(zone) || self.rotating.contains(zone)
    }

    pub fn wildcard_zones(&self) -> Vec<String> {
        let mut zones: BTreeSet<String> = self.wildcard_ips.keys().cloned().collect();
        zones.extend(self.rotating.iter().cloned());
        zones.into_iter().collect()
    }

    /// Whether `hostname` resolving to `ips` is just the wildcard answering.
    ///
    /// Checks every ancestor zone, because a wildcard can sit at any level:
    /// `*.dev.example.com` catches `x.dev.example.com` while `example.com`
    /// itself is perfectly well behaved.
    pub fn is_wildcard_answer(&self, hostname: &str, ips: &[IpAddr]) -> bool {
        if ips.is_empty() {
            return false;
        }
        let observed: HashSet<IpAddr> = ips.iter().copied().collect();

        for zone in ancestor_zones(hostname) {
            if self.rotating.contains(&zone) {
                return true;
            }
            if let Some(wildcard) = self.wildcard_ips.get(&zone) {
                // A name is only the wildcard if it adds nothing to it. A host
                // that answers with the wildcard address *and* one of its own
                // is a real host behind a catch-all, and is kept.
                if observed.is_subset(wildcard) {
                    return true;
                }
            }
        }
        false
    }
}

/// Every ancestor zone of a hostname, closest first: `a.b.example.com` yields
/// `b.example.com`, `example.com`, `com`.
fn ancestor_zones(hostname: &str) -> Vec<String> {
    let labels: Vec<&str> = hostname.split('.').collect();
    (1..labels.len())
        .map(|index| labels[index..].join("."))
        .collect()
}

/// A hostname confirmed to resolve, and how it was found.
#[derive(Debug, Clone)]
pub struct ResolvedHost {
    pub hostname: String,
    pub ips: Vec<IpAddr>,
}

/// Everything the active stage produced for one zone.
#[derive(Debug, Clone, Default)]
pub struct ActiveDnsResult {
    pub bruteforced: Vec<ResolvedHost>,
    pub permutations: Vec<ResolvedHost>,
    /// Names read straight out of the NSEC chain. These are not resolved
    /// first — the zone asserting they exist *is* the evidence.
    pub nsec_names: Vec<String>,
    /// `(srv label, target hostname)` pairs.
    pub srv_targets: Vec<(String, String)>,
    pub wildcard: WildcardProfile,
    pub warnings: Vec<String>,
}

impl ActiveDnsResult {
    /// Every hostname found, deduplicated, in a stable order.
    pub fn all_hostnames(&self) -> Vec<String> {
        let mut seen: BTreeSet<String> = BTreeSet::new();
        for host in self.bruteforced.iter().chain(self.permutations.iter()) {
            seen.insert(host.hostname.clone());
        }
        seen.extend(self.nsec_names.iter().cloned());
        seen.extend(self.srv_targets.iter().map(|(_, target)| target.clone()));
        seen.into_iter().collect()
    }
}

/// Runs the active DNS techniques against a zone.
pub struct ActiveDnsDiscovery {
    resolver: Arc<DnsResolver>,
    config: ActiveDnsConfig,
}

impl ActiveDnsDiscovery {
    pub fn new(resolver: Arc<DnsResolver>, config: ActiveDnsConfig) -> Self {
        Self { resolver, config }
    }

    pub fn config(&self) -> &ActiveDnsConfig {
        &self.config
    }

    /// Run every enabled technique against `domain`.
    ///
    /// `known_hostnames` are the names the passive stage already found; they
    /// seed permutation and are excluded from the brute-force candidate set so
    /// the same name is not resolved twice.
    pub async fn discover(&self, domain: &str, known_hostnames: &[String]) -> ActiveDnsResult {
        let mut result = ActiveDnsResult::default();

        // Step 0 — characterise the wildcard before trusting a single answer.
        result.wildcard = self.profile_wildcards(domain, known_hostnames).await;
        for zone in result.wildcard.wildcard_zones() {
            result
                .warnings
                .push(format!("Wildcard DNS detected at *.{zone}"));
        }

        // Step 1 — NSEC walk. When it works it is authoritative and complete,
        // which makes guessing largely redundant, so it runs first.
        if self.config.nsec_walk_enabled {
            match self.nsec_walk(domain).await {
                Ok(names) if !names.is_empty() => {
                    tracing::info!(
                        "NSEC walk enumerated {} names from the signed zone {}",
                        names.len(),
                        domain
                    );
                    result.nsec_names = names;
                }
                Ok(_) => {}
                Err(e) => tracing::debug!("NSEC walk not available for {}: {}", domain, e),
            }
        }

        if self.config.srv_probe_enabled {
            result.srv_targets = self.probe_srv_records(domain).await;
        }

        let mut already_known: HashSet<String> =
            known_hostnames.iter().map(|h| h.to_lowercase()).collect();
        already_known.extend(result.nsec_names.iter().cloned());

        if self.config.bruteforce_enabled {
            let candidates = self.bruteforce_candidates(domain, &already_known);
            result.bruteforced = self.resolve_candidates(candidates, &result.wildcard).await;
            already_known.extend(result.bruteforced.iter().map(|h| h.hostname.clone()));
        }

        // Step 4 — permutation, last, because it mutates everything found above.
        if self.config.permutations_enabled {
            let seeds: Vec<String> = already_known
                .iter()
                .filter(|hostname| is_within(hostname, domain))
                .take(self.config.max_permutation_seeds)
                .cloned()
                .collect();
            let candidates = self.permutation_candidates(domain, &seeds, &already_known);
            result.permutations = self.resolve_candidates(candidates, &result.wildcard).await;
        }

        result
    }

    // ------------------------------------------------------------------
    // Wildcard detection
    // ------------------------------------------------------------------

    /// Probe the apex and every intermediate zone under it for wildcards.
    ///
    /// Intermediate zones matter: `*.dev.example.com` is common and would
    /// otherwise make every generated `*.dev.example.com` candidate look real.
    async fn profile_wildcards(&self, domain: &str, known: &[String]) -> WildcardProfile {
        let mut zones: BTreeSet<String> = BTreeSet::new();
        zones.insert(domain.to_lowercase());
        for hostname in known {
            for zone in ancestor_zones(&hostname.to_lowercase()) {
                // Only zones at or below the target; `com` is not ours to probe.
                if is_within(&zone, domain) {
                    zones.insert(zone);
                }
            }
        }

        let mut profile = WildcardProfile::default();
        let zones: Vec<String> = zones.into_iter().collect();

        let probes = stream::iter(zones.into_iter().map(|zone| async move {
            let observations = self.probe_zone_wildcard(&zone).await;
            (zone, observations)
        }))
        .buffer_unordered(self.config.concurrency.min(16))
        .collect::<Vec<_>>()
        .await;

        for (zone, observations) in probes {
            // Every probe must have answered. If a random label failed to
            // resolve even once, the zone is not a catch-all.
            if observations.len() < WILDCARD_PROBE_COUNT
                || observations.iter().any(|ips| ips.is_empty())
            {
                continue;
            }

            let first = &observations[0];
            let stable = observations.iter().all(|ips| ips == first);
            if stable {
                profile.wildcard_ips.insert(zone, first.clone());
            } else {
                // Different answers for different nonsense labels: the zone is
                // synthesising responses, so resolution proves nothing here.
                profile.rotating.insert(zone);
            }
        }

        profile
    }

    async fn probe_zone_wildcard(&self, zone: &str) -> Vec<HashSet<IpAddr>> {
        let mut observations = Vec::with_capacity(WILDCARD_PROBE_COUNT);
        for _ in 0..WILDCARD_PROBE_COUNT {
            let probe = format!("{}.{}", random_label(20), zone);
            match self.resolver.resolve_hostname(&probe).await {
                Ok(ips) => observations.push(ips.into_iter().collect::<HashSet<IpAddr>>()),
                // NXDOMAIN for a random label is the expected, healthy case.
                Err(_) => return Vec::new(),
            }
        }
        observations
    }

    // ------------------------------------------------------------------
    // Brute force
    // ------------------------------------------------------------------

    fn bruteforce_candidates(&self, domain: &str, already_known: &HashSet<String>) -> Vec<String> {
        let words = self.load_wordlist();
        words
            .into_iter()
            .take(self.config.max_bruteforce_words)
            .map(|label| format!("{}.{}", label, domain))
            .filter(|candidate| !already_known.contains(candidate))
            .collect()
    }

    /// The label list, from the operator's file when configured, else built in.
    ///
    /// A missing or unreadable file falls back to the built-in list rather than
    /// silently disabling brute force — a typo in a path should not quietly
    /// shrink the attack surface being measured.
    fn load_wordlist(&self) -> Vec<String> {
        if let Some(path) = self.config.wordlist_path.as_deref() {
            match std::fs::read_to_string(path) {
                Ok(contents) => {
                    let words = parse_wordlist(&contents);
                    if !words.is_empty() {
                        tracing::info!("Loaded {} brute-force labels from {}", words.len(), path);
                        return words;
                    }
                    tracing::warn!("Wordlist {} is empty; using the built-in list", path);
                }
                Err(e) => tracing::warn!(
                    "Could not read wordlist {} ({}); using the built-in list",
                    path,
                    e
                ),
            }
        }
        parse_wordlist(DEFAULT_SUBDOMAIN_WORDLIST)
    }

    // ------------------------------------------------------------------
    // Permutations
    // ------------------------------------------------------------------

    /// Generate mutations of known-good names.
    ///
    /// Patterns, applied to the leftmost label of each seed (`api` in
    /// `api.example.com`):
    ///
    /// - `word-label`, `label-word` — the dominant real-world convention
    /// - `wordlabel`, `labelword`   — the same without the separator
    /// - `word.label`               — promoting the word to its own level
    /// - numeric successors         — `api1` → `api2`, `api` → `api2`
    fn permutation_candidates(
        &self,
        domain: &str,
        seeds: &[String],
        already_known: &HashSet<String>,
    ) -> Vec<String> {
        let words = parse_wordlist(DEFAULT_PERMUTATION_WORDS);
        let cap = self.config.max_permutations.min(PERMUTATION_HARD_CAP);

        let mut generated: HashSet<String> = HashSet::new();
        let mut candidates: Vec<String> = Vec::new();

        for seed in seeds {
            let Some((head, rest)) = seed.split_once('.') else {
                continue;
            };
            if rest.is_empty() {
                continue;
            }

            let mut variants: Vec<String> = Vec::new();
            for word in &words {
                if word == head {
                    continue;
                }
                variants.push(format!("{}-{}", word, head));
                variants.push(format!("{}-{}", head, word));
                variants.push(format!("{}{}", word, head));
                variants.push(format!("{}{}", head, word));
                variants.push(format!("{}.{}", word, head));
            }
            variants.extend(numeric_successors(head));

            for variant in variants {
                if candidates.len() >= cap {
                    return candidates;
                }
                let candidate = format!("{}.{}", variant, rest);
                if !is_within(&candidate, domain) {
                    continue;
                }
                if already_known.contains(&candidate) {
                    continue;
                }
                if generated.insert(candidate.clone()) {
                    candidates.push(candidate);
                }
            }
        }

        candidates
    }

    // ------------------------------------------------------------------
    // Resolution
    // ------------------------------------------------------------------

    /// Resolve candidates concurrently, discarding wildcard answers.
    async fn resolve_candidates(
        &self,
        candidates: Vec<String>,
        wildcard: &WildcardProfile,
    ) -> Vec<ResolvedHost> {
        if candidates.is_empty() {
            return Vec::new();
        }

        let total = candidates.len();
        let resolved: Vec<ResolvedHost> = stream::iter(candidates.into_iter().map(|candidate| {
            let resolver = Arc::clone(&self.resolver);
            async move {
                match resolver.resolve_hostname(&candidate).await {
                    Ok(ips) if !ips.is_empty() => Some(ResolvedHost {
                        hostname: candidate,
                        ips,
                    }),
                    _ => None,
                }
            }
        }))
        .buffer_unordered(self.config.concurrency)
        .filter_map(|found| async move { found })
        .collect()
        .await;

        let before = resolved.len();
        let mut kept: Vec<ResolvedHost> = resolved
            .into_iter()
            .filter(|host| !wildcard.is_wildcard_answer(&host.hostname, &host.ips))
            .collect();
        kept.sort_by(|a, b| a.hostname.cmp(&b.hostname));

        tracing::debug!(
            "Active DNS: {} candidates, {} resolved, {} survived wildcard filtering",
            total,
            before,
            kept.len()
        );
        kept
    }

    // ------------------------------------------------------------------
    // NSEC zone walking
    // ------------------------------------------------------------------

    /// Walk a signed zone's NSEC chain.
    ///
    /// Each NSEC record names the next owner in canonical order, so querying
    /// that owner yields the next link. The walk ends when the chain wraps back
    /// to the apex. A zone signed with NSEC3 returns hashes instead and is
    /// reported as not walkable rather than half-walked.
    pub async fn nsec_walk(&self, domain: &str) -> Result<Vec<String>, ApiError> {
        let apex = domain.trim_end_matches('.').to_lowercase();
        let timeout = self.config.query_timeout;

        // Cheap precondition: an unsigned zone has no NSEC to follow, and a
        // NSEC3 zone cannot be walked without offline hash cracking.
        let apex_probe = dns_wire::query_system_with_authority(
            &format!("{}.{}", random_label(16), apex),
            dns_wire::TYPE_A,
            timeout,
        )
        .await
        .map_err(ApiError::ExternalService)?;

        if !apex_probe.records_of_type("NSEC3").is_empty() {
            return Err(ApiError::ExternalService(format!(
                "{} is signed with NSEC3; the zone cannot be walked",
                apex
            )));
        }
        if apex_probe.records_of_type("NSEC").is_empty() {
            return Err(ApiError::ExternalService(format!(
                "{} does not serve NSEC records",
                apex
            )));
        }

        let mut names: BTreeSet<String> = BTreeSet::new();
        let mut current = apex.clone();

        for _ in 0..NSEC_MAX_STEPS {
            let answer =
                match dns_wire::query_system_with_authority(&current, dns_wire::TYPE_NSEC, timeout)
                    .await
                {
                    Ok(answer) => answer,
                    Err(e) => {
                        tracing::debug!("NSEC walk of {} stopped at {}: {}", apex, current, e);
                        break;
                    }
                };

            let Some(next) = answer
                .records_of_type("NSEC")
                .into_iter()
                .map(|record| record.value.trim_end_matches('.').to_lowercase())
                .find(|next| !next.is_empty() && next != &current)
            else {
                break;
            };

            // The chain is circular: reaching the apex again means it is done.
            if next == apex || !is_within(&next, &apex) {
                break;
            }
            if !names.insert(next.clone()) {
                // Revisiting a name means the chain loops; stop rather than spin.
                break;
            }
            current = next;
        }

        Ok(names.into_iter().collect())
    }

    // ------------------------------------------------------------------
    // SRV probing
    // ------------------------------------------------------------------

    /// Query the well-known `_service._proto` labels and collect their targets.
    ///
    /// SRV targets are high-value: `_autodiscover._tcp` and `_ldap._tcp` point
    /// at mail and directory infrastructure that is rarely linked from anywhere
    /// a crawler would reach.
    async fn probe_srv_records(&self, domain: &str) -> Vec<(String, String)> {
        let services = parse_wordlist(DEFAULT_SRV_SERVICES);

        let found: Vec<(String, String)> = stream::iter(services.into_iter().map(|service| {
            let resolver = Arc::clone(&self.resolver);
            let name = format!("{}.{}", service, domain);
            async move {
                let records = resolver.lookup_records(&name, RecordType::SRV).await.ok()?;
                let targets: Vec<(String, String)> = records
                    .into_iter()
                    .filter_map(|record| match record.data() {
                        Some(RData::SRV(srv)) => {
                            let target = srv.target().to_utf8();
                            let target = target.trim_end_matches('.').to_lowercase();
                            // `.` as a target is SRV's explicit "no service here".
                            if target.is_empty() || target == "." {
                                None
                            } else {
                                Some((service.clone(), target))
                            }
                        }
                        _ => None,
                    })
                    .collect();
                if targets.is_empty() {
                    None
                } else {
                    Some(targets)
                }
            }
        }))
        .buffer_unordered(self.config.concurrency.min(32))
        .filter_map(|found| async move { found })
        .flat_map(stream::iter)
        .collect()
        .await;

        let mut seen: HashSet<(String, String)> = HashSet::new();
        let mut unique: Vec<(String, String)> = Vec::new();
        for pair in found {
            if seen.insert(pair.clone()) {
                unique.push(pair);
            }
        }
        unique.sort();
        unique
    }
}

// ============================================================================
// Free functions
// ============================================================================

/// Whether `hostname` is the zone itself or sits under it.
///
/// String suffix matching alone is wrong: `notexample.com` ends with
/// `example.com` but belongs to somebody else. The dot is the point.
pub fn is_within(hostname: &str, zone: &str) -> bool {
    let hostname = hostname.trim_end_matches('.').to_lowercase();
    let zone = zone.trim_end_matches('.').to_lowercase();
    hostname == zone || hostname.ends_with(&format!(".{}", zone))
}

/// Parse a wordlist: one entry per line, `#` comments and blanks ignored.
fn parse_wordlist(contents: &str) -> Vec<String> {
    let mut seen: HashSet<String> = HashSet::new();
    contents
        .lines()
        .map(|line| line.trim().to_lowercase())
        .filter(|line| !line.is_empty() && !line.starts_with('#'))
        .filter(|line| seen.insert(line.clone()))
        .collect()
}

/// A random label that cannot plausibly exist, for wildcard probing.
fn random_label(length: usize) -> String {
    const ALPHABET: &[u8] = b"abcdefghijklmnopqrstuvwxyz0123456789";
    let mut rng = rand::thread_rng();
    // A leading letter keeps the label valid everywhere.
    let mut label = String::with_capacity(length);
    label.push(char::from(ALPHABET[rng.gen_range(0..26)]));
    for _ in 1..length {
        label.push(char::from(ALPHABET[rng.gen_range(0..ALPHABET.len())]));
    }
    label
}

/// Numeric neighbours of a label: `api1` → `api`, `api2`, `api01`, `api3`…
///
/// Sequentially numbered hosts are the most reliably productive permutation
/// there is — finding `web1` almost always means `web2` exists too.
fn numeric_successors(label: &str) -> Vec<String> {
    let mut out: Vec<String> = Vec::new();

    let digit_start = label
        .char_indices()
        .rev()
        .take_while(|(_, c)| c.is_ascii_digit())
        .last()
        .map(|(index, _)| index);

    match digit_start {
        Some(index) if index > 0 => {
            let (stem, digits) = label.split_at(index);
            let width = digits.len();
            if let Ok(value) = digits.parse::<u32>() {
                for next in value.saturating_sub(1)..=value.saturating_add(3) {
                    if next == value {
                        continue;
                    }
                    // Preserve zero padding: `web01` → `web02`, not `web2`.
                    out.push(format!("{}{:0width$}", stem, next, width = width));
                }
            }
            out.push(stem.to_string());
        }
        // No trailing digits: append the low numbers.
        _ => {
            for suffix in ["1", "2", "3", "01", "02"] {
                out.push(format!("{}{}", label, suffix));
            }
        }
    }

    out
}

#[cfg(test)]
mod tests {
    use super::*;

    #[test]
    fn ancestor_zones_walks_up_one_label_at_a_time() {
        assert_eq!(
            ancestor_zones("a.b.example.com"),
            vec![
                "b.example.com".to_string(),
                "example.com".to_string(),
                "com".to_string()
            ]
        );
        assert!(ancestor_zones("com").is_empty());
    }

    #[test]
    fn is_within_requires_a_label_boundary() {
        assert!(is_within("www.example.com", "example.com"));
        assert!(is_within("example.com", "example.com"));
        assert!(is_within("EXAMPLE.com.", "example.com"));
        // The classic false positive.
        assert!(!is_within("notexample.com", "example.com"));
        assert!(!is_within("example.com.evil.net", "example.com"));
    }

    #[test]
    fn wildcard_answers_are_rejected_but_real_hosts_behind_them_are_kept() {
        let mut profile = WildcardProfile::default();
        profile.wildcard_ips.insert(
            "example.com".to_string(),
            HashSet::from(["1.2.3.4".parse().unwrap()]),
        );

        // Exactly the wildcard answer: not a real host.
        assert!(profile.is_wildcard_answer("nonsense.example.com", &["1.2.3.4".parse().unwrap()]));
        // A different address: a real host.
        assert!(!profile.is_wildcard_answer("real.example.com", &["5.6.7.8".parse().unwrap()]));
        // The wildcard address plus one of its own: still a real host.
        assert!(!profile.is_wildcard_answer(
            "real.example.com",
            &["1.2.3.4".parse().unwrap(), "5.6.7.8".parse().unwrap()]
        ));
        // A different zone is unaffected.
        assert!(!profile.is_wildcard_answer("host.other.com", &["1.2.3.4".parse().unwrap()]));
    }

    #[test]
    fn a_wildcard_on_an_intermediate_zone_filters_names_below_it() {
        let mut profile = WildcardProfile::default();
        profile.wildcard_ips.insert(
            "dev.example.com".to_string(),
            HashSet::from(["10.0.0.1".parse().unwrap()]),
        );

        assert!(
            profile.is_wildcard_answer("anything.dev.example.com", &["10.0.0.1".parse().unwrap()])
        );
        // The apex is not wildcarded, so a name directly under it is real.
        assert!(!profile.is_wildcard_answer("www.example.com", &["10.0.0.1".parse().unwrap()]));
    }

    #[test]
    fn a_rotating_wildcard_rejects_everything_under_it() {
        let mut profile = WildcardProfile::default();
        profile.rotating.insert("example.com".to_string());
        assert!(profile.is_wildcard_answer("anything.example.com", &["9.9.9.9".parse().unwrap()]));
    }

    #[test]
    fn numeric_successors_preserve_zero_padding() {
        let out = numeric_successors("web01");
        assert!(out.contains(&"web02".to_string()));
        assert!(out.contains(&"web03".to_string()));
        assert!(out.contains(&"web".to_string()));
        assert!(!out.contains(&"web2".to_string()));

        let out = numeric_successors("web1");
        assert!(out.contains(&"web2".to_string()));
        assert!(out.contains(&"web".to_string()));

        // No digits: append them.
        let out = numeric_successors("api");
        assert!(out.contains(&"api1".to_string()));
        assert!(out.contains(&"api01".to_string()));
    }

    #[test]
    fn numeric_successors_ignore_an_all_digit_label() {
        // `123.example.com` — there is no stem to keep, so nothing is emitted
        // beyond the plain suffixes.
        let out = numeric_successors("123");
        assert!(out.contains(&"1231".to_string()));
    }

    #[test]
    fn random_labels_start_with_a_letter_and_differ() {
        let a = random_label(20);
        let b = random_label(20);
        assert_eq!(a.len(), 20);
        assert!(a.chars().next().unwrap().is_ascii_alphabetic());
        assert_ne!(a, b, "two probes must not collide");
    }

    #[test]
    fn wordlists_parse_and_are_deduplicated() {
        let words = parse_wordlist("www\n# comment\n\nWWW\nmail\n  api  \n");
        assert_eq!(
            words,
            vec!["www".to_string(), "mail".to_string(), "api".to_string()]
        );
    }

    #[test]
    fn builtin_wordlists_are_populated_and_clean() {
        let subdomains = parse_wordlist(DEFAULT_SUBDOMAIN_WORDLIST);
        assert!(subdomains.len() > 300, "built-in wordlist is too small");
        assert_eq!(
            subdomains[0], "www",
            "highest-yield label should come first"
        );
        assert!(subdomains
            .iter()
            .all(|word| !word.contains('.') && !word.contains(' ')));

        assert!(parse_wordlist(DEFAULT_PERMUTATION_WORDS).len() > 40);

        let srv = parse_wordlist(DEFAULT_SRV_SERVICES);
        assert!(srv.iter().all(|label| label.starts_with('_')));
        assert!(srv.contains(&"_autodiscover._tcp".to_string()));
    }

    #[tokio::test]
    async fn permutations_stay_inside_the_target_zone_and_respect_the_cap() {
        let resolver = Arc::new(
            DnsResolver::new()
                .await
                .expect("a resolver can be constructed"),
        );
        let discovery = ActiveDnsDiscovery::new(
            resolver,
            ActiveDnsConfig {
                max_permutations: 50,
                ..Default::default()
            },
        );

        let seeds = vec!["api.example.com".to_string()];
        let candidates = discovery.permutation_candidates("example.com", &seeds, &HashSet::new());

        assert!(!candidates.is_empty());
        assert!(candidates.len() <= 50, "the cap must be respected");
        assert!(candidates
            .iter()
            .all(|candidate| is_within(candidate, "example.com")));
        assert!(candidates.contains(&"dev-api.example.com".to_string()));
    }

    #[tokio::test]
    async fn bruteforce_candidates_skip_names_already_known() {
        let resolver = Arc::new(
            DnsResolver::new()
                .await
                .expect("a resolver can be constructed"),
        );
        let discovery = ActiveDnsDiscovery::new(resolver, ActiveDnsConfig::default());

        let known = HashSet::from(["www.example.com".to_string()]);
        let candidates = discovery.bruteforce_candidates("example.com", &known);

        assert!(!candidates.contains(&"www.example.com".to_string()));
        assert!(candidates.contains(&"mail.example.com".to_string()));
    }
}
